#!/bin/sh
# Polish pass 3: short recordings of the stage moments. Usage (inside scripts/withphone): scenes.sh [names...]
# names: cold sheet catchup stopwatch nowcard island card auto voice center blockers
set -u; cd "$(dirname "$0")"; S=${ANDROID_SERIAL:-ZY22J3TK8S}; A="adb -s $S shell"; UI="am broadcast -a local.agentos.UI"
D="node drive.mjs"; home() { $A "input keyevent KEYCODE_HOME; sleep .6; input keyevent KEYCODE_HOME"; sleep 1; }
home
for n in ${@:-cold sheet catchup stopwatch nowcard island card auto voice center blockers}; do echo "== $n"; case $n in
  cold)      ./rec.sh cold 5 "$A 'am force-stop local.agentos.home; sleep .3; am start -n local.agentos.home/.Home' >/dev/null"; sleep 2;;
  sheet)     home; ./rec.sh sheet 5 "$A input tap 300 1240; sleep 2.2; $A input keyevent KEYCODE_BACK; sleep .4; $A input keyevent KEYCODE_BACK";;
  catchup)   home; $A input tap 300 1240; sleep 1.5; $A input keyevent KEYCODE_BACK; sleep .5
             ./rec.sh catchup 6 "$D \"window.fake=(t)=>{open('sheet');body.append(el('div','msg me',esc(t)));aiMsg=null;askAt=Date.now();sheetEmpty();S.turn=true;setSheet('Thinking','working');think();renderStatus();renderNow()};fake('What did I miss?')\" >/dev/null; sleep 1.4; $D \"emit({type:'catchup',cards:[{icon:'chat',title:'Sam · Pigeon',detail:'12 min ago: Are we still on for 3?',goal:'Reply to Sam in Pigeon'},{icon:'chat',title:'Mom · Pigeon',detail:'1 h ago: Call me when you land',goal:'Reply to Mom in Pigeon'},{icon:'cal',title:'Standup',detail:'10:15 AM'},{icon:'spark',title:'Your promise to Dana',detail:'Pigeon · due today',goal:'x'},{icon:'shield',title:'1 scam message hidden'}]})\" >/dev/null; sleep .3; $D \"'Two messages are waiting, standup is at 10:15, and you promised Dana a reply today.'.split(' ').forEach((w,i)=>setTimeout(()=>emit({type:'text.delta',text:w+' '}),i*60))\" >/dev/null; sleep 1.4; $D \"emit({type:'turn.done',status:'completed',ms:1840})\" >/dev/null"
             sleep 1; $A input keyevent KEYCODE_BACK; sleep .3; $A input keyevent KEYCODE_BACK; $D "body.replaceChildren(); aiMsg=null; setSheet('Ask','')" >/dev/null;;
  stopwatch) home; ./rec.sh stopwatch 9 "$D \"window.fake=(t)=>{open('sheet');body.append(el('div','msg me',esc(t)));aiMsg=null;askAt=Date.now();sheetEmpty();S.turn=true;setSheet('Thinking','working');think();renderStatus();renderNow()};fake('How much battery do I have?')\" >/dev/null; sleep 2.5; $D \"emit({type:'tool.request',name:'device.status',args:{}})\" >/dev/null; sleep 1.5; $D \"emit({type:'tool.result',name:'device.status',ok:true})\" >/dev/null; sleep .6; $D \"'Your battery is at 100% and charging.'.split(' ').forEach((w,i)=>setTimeout(()=>emit({type:'text.delta',text:w+' '}),i*70))\" >/dev/null; sleep 1.2; $D \"emit({type:'turn.done',status:'completed',ms:6800})\" >/dev/null"
             sleep .5; $A input keyevent KEYCODE_BACK; sleep .3; $A input keyevent KEYCODE_BACK; $D "body.replaceChildren(); aiMsg=null; setSheet('Ask','')" >/dev/null;;
  nowcard)   home; ./rec.sh nowcard 9 "$D \"S.tasks.set('opt1',{id:'opt',goal:'Text Mom that I am late',state:'queued',step:'Starting',steps:0,created:Date.now()});renderNow()\" >/dev/null; sleep 1.5; $D \"emit({type:'task.update',why:'created',task:{id:'t9',goal:'Text Mom that I am late',state:'running',step:'Opening Pigeon',steps:1,created:Date.now()-1500}})\" >/dev/null; sleep 2; $D \"emit({type:'task.update',task:{id:'t9',goal:'Text Mom that I am late',state:'running',step:'Typing in Pigeon',steps:3,created:Date.now()-3500}})\" >/dev/null; sleep 2; $D \"emit({type:'task.update',task:{id:'t9',goal:'Text Mom that I am late',state:'done',step:'Done',steps:5,result:'Sent.',created:Date.now()-5500,timing:{total_ms:6800}}})\" >/dev/null"
             $D "S.tasks.delete('t9'); renderNow(); body.replaceChildren(); aiMsg=null; setSheet('Ask','')" >/dev/null;;
  island)    home; ./rec.sh island 10 "$A $UI --es island working --es label \"'Opening Pigeon'\" --ei pct 10 --es goal \"'Text Mom that I am late'\" >/dev/null; sleep 2; $A $UI --es island working --es label \"'Typing in Pigeon'\" --ei pct 45 >/dev/null; sleep 2; $A $UI --es island done --es label \"'Done · 6.8 s'\" >/dev/null";;
  card)      home; ./rec.sh card 7 "$A $UI --es island working --es label \"'Typing in Pigeon'\" --ei pct 35 >/dev/null; sleep 1.5; $A $UI --es card approval >/dev/null; sleep 3; $A $UI --es island hide >/dev/null";;
  auto)      home; ./rec.sh auto 8 "$A $UI --es island working --es label \"'Typing in Pigeon'\" --ei pct 35 >/dev/null; sleep 1.5; $A $UI --es card auto >/dev/null; sleep 4; $A $UI --es island hide >/dev/null";;
  voice)     home; ./rec.sh voice 7 "$A input tap 640 1240; sleep 3.5; $A input tap 420 1470"; sleep 1; home;;
  center)    home; ./rec.sh center 5 "$A input swipe 600 900 100 900 160; sleep 1.8; $A input swipe 100 900 600 900 160";;
  blockers)  home; $A input swipe 600 900 100 900 120; sleep 1; $A input swipe 360 700 360 100 400; sleep .6; $A input swipe 360 1400 360 400 400; sleep 1
             ./rec.sh blockers 6 "$A input tap 530 760; sleep 2.5; $D \"[...document.querySelectorAll('#blockers .n')].forEach((e)=>tick(e,(+e.dataset.v||0)+7))\" >/dev/null; sleep 1.5; $A input keyevent KEYCODE_BACK"; home;;
esac; done
home
